#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    /* Parse shift value */
    char *endptr;
    long shift = strtol(argv[1], &endptr, 10);
    (void)endptr; // ignore validation – original program treats 0 as a valid shift

    /* Reduce shift to the range [0,25] */
    shift %= 26;
    if (shift < 0)
        shift += 26;

    const char *input = argv[2];
    size_t len = strlen(input);
    for (size_t i = 0; i < len; ++i) {
        unsigned char c = (unsigned char)input[i];
        if (c >= 'A' && c <= 'Z') {
            c = ((c - 'A' + shift) % 26) + 'A';
        } else if (c >= 'a' && c <= 'z') {
            c = ((c - 'a' + shift) % 26) + 'a';
        }
        putchar(c);
    }
    putchar('\n');
    return 0;
}
